questionvariables.text:
/* Part (a) */
questionType:rand(["time", "distance"]);
speedA:rand_with_step(100,200,5)/10;
timeA:(rand(31)+10)/10;
distA:speedA*timeA*18/5;

tansA: if questionType="time" then timeA else distA;

/* Part (b) */
speedB:rand_with_step(10,50,5)/1000;
timeB:rand_with_step(15,30,3);

distBmet:speedB*timeB*50/3;
distBunits:rand(["m","cm","mm"]);
distBdisp:if distBunits="mm" then distBmet*1000 else if distBunits="cm" then distBmet*100 else distBmet;

timeStart:60-rand(timeB-1)-1;
timeEnd:timeStart+timeB-60;
timeHour:rand(7)+10;

feedbackvariables.text:
/* Node 1: Check correct answer */
/* Node 2: Worked solution */

/* Node 3: Check whether speed is converted incorrectly, divided by 3.6 instead of multiplying (1) */
node3_test: if (questionType="time" and abs(ans1-3.6*distA/speedA)<10^(-4)) or (questionType="distance" and abs(ans1-timeA*speedA/3.6)<10^(-4)) then 1 else 0;

/* Node 4: Check whether student used incorrect SDT equation, S=DT or S=T/D (1) */
node4_test: if (questionType="time" and (abs(ans1-speedA*3.6/distA)<10^(-4) or abs(ans1-speedA*3.6*distA)<10^(-4))) or (questionType="distance" and (abs(ans1-speedA*3.6/timeA)<10^(-4) or abs(ans1-timeA/(speedA*3.6))<10^(-4))) then 1 else 0;

/* Node 5: Check whether used speed as given without conversion */
node5_test: if (questionType="time" and abs(ans1-distA/speedA)<10^(-4)) or (questionType="distance" and abs(ans1-timeA*speedA)<10^(-4)) then 1 else 0;

/* Node 6: node3 and node5 errors combined */
node6_test: if (questionType="time" and (abs(ans1-speedA/(3.6*distA))<10^(-4) or abs(ans1-speedA*distA/3.6)<10^(-4))) or (questionType="distance" and (abs(ans1-speedA/(3.6*timeA))<10^(-4) or abs(ans1-3.6*timeA/speedA)<10^(-4))) then 1 else 0;

/* Node 7: node4 and node5 errors combined */
node7_test: if (questionType="time" and (abs(ans1-speedA/distA)<10^(-4) or abs(ans1-speedA*distA)<10^(-4))) or (questionType="distance" and (abs(ans1-speedA/timeA)<10^(-4) or abs(ans1-timeA/speedA)<10^(-4))) then 1 else 0;

/* Node 1: Check correct answer */
/* Node 2: Worked solution */
/* Node 3: Incorrect SDT equation used (1) */
node3_test: if abs(ans2-(distBmet/1000)*(timeB/60))<10^(-4) or abs(ans2-(timeB/60)/(distBmet/1000))<10^(-4) then 1 else 0;

/* Node 4: Units of time not converted or converted incorrectly (1) */
node4_test: if abs(ans2-(distBmet/1000)/timeB)<10^(-4) or abs(ans2-(distBmet/1000)/(timeB*60))<10^(-4) then 1 else 0;

/* Node 5: Units of distance not converted or converted incorrectly (1) */
node5_test: if abs(ans2-distBdisp/(timeB/60))<10^(-4) or (distBunits="m" and abs(ans2-(distBmet*1000)/(timeB/60))<10^(-4)) or (distBunits="cm" and (abs(ans2-(distBmet*100)/(timeB/60))<10^(-4) or abs(ans2-(distBmet*100000)/(timeB/60))<10^(-4))) or (distBunits="mm" and (abs(ans2-(distBmet*1000)/(timeB/60))<10^(-4) or abs(ans2-(distBmet*1000000)/(timeB/60))<10^(-4))) then 1 else 0;

/* Node 6: Neither units converted or both converted incorrectly */
node6_test: if abs(ans2-distBdisp/timeB)<10^(-4) or (distBunits="m" and abs(ans2-(distBmet*1000)/timeB)<10^(-4)) or (distBunits="cm" and (abs(ans2-(distBmet*100)/timeB)<10^(-4) or abs(ans2-(distBmet*100000)/timeB)<10^(-4))) or (distBunits="mm" and (abs(ans2-(distBmet*1000)/timeB)<10^(-4) or abs(ans2-(distBmet*1000000)/timeB)<10^(-4))) or abs(ans2-distBdisp/(timeB*60))<10^(-4) or (distBunits="m" and abs(ans2-(distBmet*1000)/(timeB*60))<10^(-4)) or (distBunits="cm" and (abs(ans2-(distBmet*100)/(timeB*60))<10^(-4) or abs(ans2-(distBmet*100000)/(timeB*60))<10^(-4))) or (distBunits="mm" and (abs(ans2-(distBmet*1000)/(timeB*60))<10^(-4) or abs(ans2-(distBmet*1000000)/(timeB*60))<10^(-4))) then 1 else 0;

/* Node 7: Incorrect unit conversion and incorrect SDT equation */
node7_test: if abs(ans2-distBdisp*timeB)<10^(-4) or (distBunits="m" and abs(ans2-(distBmet*1000)*timeB)<10^(-4)) or (distBunits="cm" and (abs(ans2-(distBmet*100)*timeB)<10^(-4) or abs(ans2-(distBmet*100000)*timeB)<10^(-4))) or (distBunits="mm" and (abs(ans2-(distBmet*1000)*timeB)<10^(-4) or abs(ans2-(distBmet*1000000)*timeB)<10^(-4))) or abs(ans2-distBdisp*(timeB*60))<10^(-4) or (distBunits="m" and abs(ans2-(distBmet*1000)*(timeB*60))<10^(-4)) or (distBunits="cm" and (abs(ans2-(distBmet*100)*(timeB*60))<10^(-4) or abs(ans2-(distBmet*100000)*(timeB*60))<10^(-4))) or (distBunits="mm" and (abs(ans2-(distBmet*1000)*(timeB*60))<10^(-4) or abs(ans2-(distBmet*1000000)*(timeB*60))<10^(-4))) or abs(ans2-timeB/distBdisp)<10^(-4) or (distBunits="m" and abs(ans2-(timeB/distBmet*1000))<10^(-4)) or (distBunits="cm" and (abs(ans2-timeB/(distBmet*100))<10^(-4) or abs(ans2-timeB/(distBmet*100000))<10^(-4))) or (distBunits="mm" and (abs(ans2-timeB/(distBmet*1000))<10^(-4) or abs(ans2-timeB/(distBmet*1000000))<10^(-4))) or abs(ans2-(timeB*60)/distBdisp)<10^(-4) or (distBunits="m" and abs(ans2-(timeB*60)/(distBmet*1000))<10^(-4)) or (distBunits="cm" and (abs(timeB*60)/(ans2-(distBmet*100))<10^(-4) or abs(ans2-(timeB*60)/(distBmet*100000))<10^(-4))) or (distBunits="mm" and (abs(ans2-(timeB*60)/(distBmet*1000))<10^(-4) or abs(ans2-(timeB*60)/(distBmet*1000000))<10^(-4))) then 1 else 0;
